package com.cartmount;

import java.awt.Color;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.gameval.ObjectID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class CartModelFactory
{
    static final int MINECART_OBJECT_ID = ObjectID.MINECART;
    private static final int OBJECT_CONFIG_ARCHIVE = 6;
    private static final int DEFAULT_OBJECT_TYPE = 10;
    private static final Logger log = LoggerFactory.getLogger(CartModelFactory.class);

    private final Client client;
    private final Map<MountType, Model> baseModels = new EnumMap<>(MountType.class);

    @Inject
    CartModelFactory(Client client)
    {
        this.client = client;
    }

    Model create(MountType type, int userScalePercent, boolean recolourMinecart,
        Color bodyColour, Color wheelColour, Color hubColour)
    {
        Model base = baseModels.get(type);
        if (base == null)
        {
            base = type.source == MountSource.OBJECT
                ? loadObjectModel(type.sourceId, recolourMinecart, bodyColour, wheelColour, hubColour)
                : loadNpcModel(type.sourceId);
            if (base != null)
            {
                baseModels.put(type, base);
            }
        }
        if (base == null)
        {
            return null;
        }

        int percent = Math.max(1, type.modelScale * userScalePercent / 100);
        if (percent == 100)
        {
            return base;
        }
        Model scaled = client.mergeModels(base);
        if (scaled == null)
        {
            return null;
        }
        int scale = Math.max(1, percent * 128 / 100);
        scaled.scale(scale, scale, scale);
        return ModelSafetyValidator.isSafe(scaled) ? scaled : null;
    }

    void clear()
    {
        baseModels.clear();
    }

    private Model loadObjectModel(int objectId, boolean recolour,
        Color bodyColour, Color wheelColour, Color hubColour)
    {
        try
        {
            byte[] bytes = client.getIndexConfig().loadData(OBJECT_CONFIG_ARCHIVE, objectId);
            if (bytes == null)
            {
                return null;
            }
            ObjectDefinitionData definition = ObjectDefinitionDecoder.decode(bytes);
            if (!definition.isSafeForCustomRendering())
            {
                log.debug("Unsupported mount object definition {}", objectId);
                return null;
            }

            List<ModelData> parts = loadObjectParts(definition, true);
            if (parts.isEmpty())
            {
                // Some scenery such as rugs is encoded as a ground-decoration type.
                parts = loadObjectParts(definition, false);
            }
            if (parts.isEmpty())
            {
                return null;
            }
            ModelData data = merge(parts);
            if (data == null)
            {
                return null;
            }
            applyObjectTransforms(data, definition);
            if (recolour && bodyColour != null && wheelColour != null && hubColour != null)
            {
                applyColours(data, bodyColour, wheelColour, hubColour);
            }
            Model model = data.light(64 + definition.ambient, 768 + definition.contrast, -50, -10, -50);
            return ModelSafetyValidator.isSafe(model) ? model : null;
        }
        catch (RuntimeException | AssertionError ex)
        {
            log.debug("Unable to build mount object " + objectId, ex);
            return null;
        }
    }

    private static void applyColours(ModelData data, Color bodyColour, Color wheelColour, Color hubColour)
    {
        short body = JagexColor.rgbToHSL(bodyColour.getRGB(), 1.0);
        short wheel = JagexColor.rgbToHSL(wheelColour.getRGB(), 1.0);
        short hub = JagexColor.rgbToHSL(hubColour.getRGB(), 1.0);
        short[] faceColours = data.getFaceColors();
        if (faceColours == null)
        {
            return;
        }
        float[] zs = data.getVerticesZ();
        int[] a = data.getFaceIndices1();
        int[] b = data.getFaceIndices2();
        int[] c = data.getFaceIndices3();
        short[] originals = faceColours.clone();
        for (int i = 0; i < faceColours.length; i++)
        {
            if ((originals[i] & 0xffff) != 20)
            {
                faceColours[i] = body;
                continue;
            }
            float centroidZ = (zs[a[i]] + zs[b[i]] + zs[c[i]]) / 3f;
            faceColours[i] = Math.abs(centroidZ) >= 55.5f ? hub : wheel;
        }
    }

    private List<ModelData> loadObjectParts(ObjectDefinitionData definition, boolean requireDefaultType)
    {
        List<ModelData> parts = new ArrayList<>();
        for (int i = 0; i < definition.modelIds.length; i++)
        {
            if (requireDefaultType && definition.modelTypes != null
                && definition.modelTypes[i] != DEFAULT_OBJECT_TYPE)
            {
                continue;
            }
            ModelData part = copyModelData(definition.modelIds[i]);
            if (part == null)
            {
                parts.clear();
                return parts;
            }
            if (definition.rotated)
            {
                part.rotateY180Ccw();
            }
            parts.add(part);
        }
        return parts;
    }

    private Model loadNpcModel(int npcId)
    {
        try
        {
            NPCComposition composition = client.getNpcDefinition(npcId);
            if (composition == null)
            {
                return null;
            }
            if (composition.getConfigs() != null)
            {
                NPCComposition transformed = composition.transform();
                if (transformed != null)
                {
                    composition = transformed;
                }
            }
            int[] ids = composition.getModels();
            if (ids == null || ids.length == 0 || ids.length > 32)
            {
                return null;
            }
            List<ModelData> parts = new ArrayList<>(ids.length);
            for (int id : ids)
            {
                ModelData part = copyModelData(id);
                if (part == null)
                {
                    return null;
                }
                parts.add(part);
            }
            ModelData data = merge(parts);
            if (data == null)
            {
                return null;
            }
            short[] from = composition.getColorToReplace();
            short[] to = composition.getColorToReplaceWith();
            if (from != null && to != null)
            {
                for (int i = 0; i < Math.min(from.length, to.length); i++)
                {
                    data.recolor(from[i], to[i]);
                }
            }
            int width = composition.getWidthScale();
            int height = composition.getHeightScale();
            if (width != 128 || height != 128)
            {
                data.scale(width, height, width);
            }
            Model model = data.light();
            return ModelSafetyValidator.isSafe(model) ? model : null;
        }
        catch (RuntimeException | AssertionError ex)
        {
            log.debug("Unable to build mount NPC " + npcId, ex);
            return null;
        }
    }

    private ModelData copyModelData(int modelId)
    {
        ModelData source = client.loadModelData(modelId);
        if (source == null)
        {
            return null;
        }
        ModelData copy = source.shallowCopy().cloneVertices().cloneColors();
        if (copy.getFaceTextures() != null)
        {
            copy = copy.cloneTextures();
        }
        if (copy.getFaceTransparencies() != null)
        {
            copy = copy.cloneTransparencies();
        }
        return copy;
    }

    private ModelData merge(List<ModelData> parts)
    {
        return parts.size() == 1 ? parts.get(0)
            : client.mergeModels(parts.toArray(new ModelData[0]));
    }

    private static void applyObjectTransforms(ModelData data, ObjectDefinitionData definition)
    {
        if (definition.recolorFrom != null)
        {
            for (int i = 0; i < definition.recolorFrom.length; i++)
            {
                data.recolor(definition.recolorFrom[i], definition.recolorTo[i]);
            }
        }
        if (definition.retextureFrom != null)
        {
            for (int i = 0; i < definition.retextureFrom.length; i++)
            {
                data.retexture(definition.retextureFrom[i], definition.retextureTo[i]);
            }
        }
        if (definition.scaleX != 128 || definition.scaleHeight != 128 || definition.scaleY != 128)
        {
            data.scale(definition.scaleX, definition.scaleHeight, definition.scaleY);
        }
        if (definition.offsetX != 0 || definition.offsetHeight != 0 || definition.offsetY != 0)
        {
            data.translate(definition.offsetX, definition.offsetHeight, definition.offsetY);
        }
    }
}

package com.cartmount;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(CartMountConfig.GROUP)
public interface CartMountConfig extends Config
{
    String GROUP = "cartMountMode";

    @Range(min = 60, max = 140)
    @ConfigItem(keyName = "cartScale", name = "Cart size",
        description = "Adjust the minecart's size", position = 0)
    default int cartScale()
    {
        return 100;
    }

    @Range(min = 0, max = 3)
    @ConfigItem(keyName = "facingOffset", name = "Facing correction",
        description = "Apply an extra rotation in quarter turns", position = 1)
    default int facingOffset()
    {
        return 0;
    }

    @Range(min = -48, max = 48)
    @ConfigItem(keyName = "groundingOffset", name = "Cart height",
        description = "Positive values lower the cart; negative values raise it", position = 2)
    default int groundingOffset()
    {
        return 0;
    }

    @ConfigItem(keyName = "idleAnimation", name = "Idle animation",
        description = "Animation used while the minecart is still", position = 3)
    default RiderAnimation idleAnimation()
    {
        return RiderAnimation.MINECART;
    }

    @ConfigItem(keyName = "walkAnimation", name = "Walk animation",
        description = "Animation used while walking in the minecart", position = 4)
    default RiderAnimation walkAnimation()
    {
        return RiderAnimation.MINECART;
    }

    @ConfigItem(keyName = "runAnimation", name = "Run animation",
        description = "Animation used while running in the minecart", position = 5)
    default RiderAnimation runAnimation()
    {
        return RiderAnimation.MINECART;
    }

    @ConfigItem(keyName = "recolourMinecart", name = "Recolour cart",
        description = "Apply custom colours to the minecart", position = 6)
    default boolean recolourMinecart()
    {
        return false;
    }

    @ConfigItem(keyName = "minecartColour", name = "Body colour",
        description = "Colour of the cart body", position = 7)
    default Color minecartColour()
    {
        return new Color(120, 70, 45);
    }

    @ConfigItem(keyName = "wheelColour", name = "Wheel colour",
        description = "Colour of the cart wheels", position = 8)
    default Color wheelColour()
    {
        return new Color(45, 45, 50);
    }

    @ConfigItem(keyName = "hubColour", name = "Wheel hub colour",
        description = "Colour of the middle caps on the wheels", position = 9)
    default Color hubColour()
    {
        return new Color(190, 145, 55);
    }

    @ConfigItem(keyName = "hideCape", name = "Hide cape",
        description = "Hide the local player's cape", position = 10)
    default boolean hideCape()
    {
        return false;
    }

    @ConfigItem(keyName = "hideWeapon", name = "Hide sword",
        description = "Hide the local player's weapon", position = 11)
    default boolean hideWeapon()
    {
        return false;
    }

    @ConfigItem(keyName = "hideShield", name = "Hide shield",
        description = "Hide the local player's shield", position = 12)
    default boolean hideShield()
    {
        return false;
    }

    @Range(min = 24, max = 96)
    @ConfigItem(keyName = "buttonSize", name = "Button size",
        description = "Size of the clickable cart button in pixels", position = 13)
    default int buttonSize()
    {
        return 44;
    }

    @ConfigItem(keyName = "togglePoof", name = "Toggle poof",
        description = "Play a small smoke poof when mounting or dismounting", position = 14)
    default boolean togglePoof()
    {
        return true;
    }

    @ConfigItem(keyName = "resetCart", name = "Reset cart",
        description = "Toggle this whenever the cart or rider pose needs to be rebuilt", position = 15)
    default boolean resetCart()
    {
        return false;
    }
}

package com.cartmount;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WorldViewLoaded;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.kit.KitType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Station's Cozy Carts",
    description = "Cruise around Gielinor in a customizable cosmetic minecart",
    tags = {"cosmetic", "cart", "minecart", "cozy", "fun"}
)
public class CartMountPlugin extends Plugin
{
    static final int MOUNTED_ANIMATION = AnimationID.HUMAN_MINECART_ANIM;
    private static final int TOGGLE_POOF_SLOT = 0x43415254;
    private static final Set<RuneLiteObject> CART_OBJECTS =
        Collections.newSetFromMap(new IdentityHashMap<>());

    @Inject
    private Client client;
    @Inject
    private CartMountConfig config;
    @Inject
    private CartModelFactory modelFactory;
    @Inject
    private CartToggleOverlay toggleOverlay;
    @Inject
    private OverlayManager overlayManager;
    @Inject
    private MouseManager mouseManager;

    private RuneLiteObject mountObject;
    private MountType activeMount;
    private Player mountedPlayer;
    private PlayerPoseSnapshot originalPose;
    private int activePoseSignature = Integer.MIN_VALUE;
    private int activeModelSignature = Integer.MIN_VALUE;
    private boolean lastResetToggle;
    private PlayerComposition hiddenComposition;
    private int[] originalEquipment;
    private int activeVisibilitySignature = Integer.MIN_VALUE;
    private volatile boolean userMounted;

    @Provides
    CartMountConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(CartMountConfig.class);
    }

    @Override
    protected void startUp()
    {
        userMounted = true;
        toggleOverlay.bind(this);
        overlayManager.add(toggleOverlay);
        mouseManager.registerMouseListener(toggleOverlay);
        lastResetToggle = config.resetCart();
        resetCartState();
    }

    @Override
    protected void shutDown()
    {
        mouseManager.unregisterMouseListener(toggleOverlay);
        overlayManager.remove(toggleOverlay);
        toggleOverlay.unbind();
        resetCartState();
        userMounted = false;
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        boolean resetToggle = config.resetCart();
        if (resetToggle != lastResetToggle)
        {
            lastResetToggle = resetToggle;
            resetCartState();
        }
        if (!userMounted)
        {
            return;
        }
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        Player player = client.getLocalPlayer();
        WorldView worldView = client.getTopLevelWorldView();
        if (player == null || worldView == null)
        {
            return;
        }
        LocalPoint location = player.getLocalLocation();
        if (location == null || location.getWorldView() != worldView.getId())
        {
            return;
        }

        int modelSignature = modelSignature();
        if (activeModelSignature != modelSignature)
        {
            clearMount();
            modelFactory.clear();
            activeModelSignature = modelSignature;
        }

        MountType type = MountType.MINECART;
        mountPlayer(player);
        ensureMount(type, location, worldView.getPlane());
        if (mountObject != null)
        {
            mountObject.setLocation(location, worldView.getPlane());
            mountObject.setZ(mountObject.getZ() + type.grounding + config.groundingOffset());
            mountObject.setOrientation((player.getCurrentOrientation()
                + (type.facingQuarterTurns + config.facingOffset()) * 512) & 2047);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            resetCartState();
        }
    }

    @Subscribe
    public void onWorldViewLoaded(WorldViewLoaded event)
    {
        clearMount();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!CartMountConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }
        if ("resetCart".equals(event.getKey()))
        {
            lastResetToggle = config.resetCart();
            resetCartState();
            return;
        }
        if ("cartScale".equals(event.getKey())
            || "recolourMinecart".equals(event.getKey()) || "minecartColour".equals(event.getKey())
            || "wheelColour".equals(event.getKey()) || "hubColour".equals(event.getKey()))
        {
            clearMount();
            modelFactory.clear();
            activeModelSignature = Integer.MIN_VALUE;
        }
    }

    private void mountPlayer(Player player)
    {
        RiderAnimation idleChoice = choice(config.idleAnimation());
        RiderAnimation walkChoice = choice(config.walkAnimation());
        RiderAnimation runChoice = choice(config.runAnimation());
        int idleAnimation = idleChoice.idleAnimationId;
        int walkAnimation = walkChoice.walkAnimationId;
        int runAnimation = runChoice.runAnimationId;

        if (mountedPlayer != player || originalPose == null)
        {
            restorePlayerPose();
            mountedPlayer = player;
            originalPose = PlayerPoseSnapshot.capture(player);
        }
        applyEquipmentVisibility(player);
        player.setIdlePoseAnimation(idleAnimation);
        player.setIdleRotateLeft(idleAnimation);
        player.setIdleRotateRight(idleAnimation);
        player.setWalkAnimation(walkAnimation);
        player.setWalkRotateLeft(walkAnimation);
        player.setWalkRotateRight(walkAnimation);
        player.setWalkRotate180(walkAnimation);
        player.setRunAnimation(runAnimation);

        int signature = 31 * (31 * idleAnimation + walkAnimation) + runAnimation;
        if (activePoseSignature != signature)
        {
            player.setPoseAnimation(idleAnimation);
            player.setPoseAnimationFrame(0);
            activePoseSignature = signature;
        }
    }

    private static RiderAnimation choice(RiderAnimation animation)
    {
        return animation == null ? RiderAnimation.MINECART : animation;
    }

    private void applyEquipmentVisibility(Player player)
    {
        int signature = (config.hideCape() ? 4 : 0)
            | (config.hideWeapon() ? 2 : 0)
            | (config.hideShield() ? 1 : 0);
        if (signature == 0)
        {
            restoreEquipment();
            activeVisibilitySignature = 0;
            return;
        }

        PlayerComposition composition = player.getPlayerComposition();
        if (composition == null)
        {
            return;
        }
        if (composition == hiddenComposition && activeVisibilitySignature == signature)
        {
            return;
        }

        restoreEquipment();
        composition = player.getPlayerComposition();
        int[] equipment = composition == null ? null : composition.getEquipmentIds();
        if (equipment == null)
        {
            return;
        }
        hiddenComposition = composition;
        originalEquipment = equipment.clone();
        activeVisibilitySignature = signature;

        if (config.hideCape())
        {
            hideSlot(equipment, KitType.CAPE);
        }
        if (config.hideWeapon())
        {
            hideSlot(equipment, KitType.WEAPON);
        }
        if (config.hideShield())
        {
            hideSlot(equipment, KitType.SHIELD);
        }
        composition.setHash();
    }

    private static void hideSlot(int[] equipment, KitType type)
    {
        int index = type.getIndex();
        if (index >= 0 && index < equipment.length)
        {
            equipment[index] = 0;
        }
    }

    private void restoreEquipment()
    {
        if (hiddenComposition != null && originalEquipment != null)
        {
            int[] equipment = hiddenComposition.getEquipmentIds();
            if (equipment != null && equipment.length == originalEquipment.length)
            {
                System.arraycopy(originalEquipment, 0, equipment, 0, equipment.length);
                hiddenComposition.setHash();
            }
        }
        hiddenComposition = null;
        originalEquipment = null;
        activeVisibilitySignature = Integer.MIN_VALUE;
    }

    private int modelSignature()
    {
        int signature = 31 * config.cartScale() + (config.recolourMinecart() ? 1 : 0);
        signature = 31 * signature + colourRgb(config.minecartColour());
        signature = 31 * signature + colourRgb(config.wheelColour());
        return 31 * signature + colourRgb(config.hubColour());
    }

    private static int colourRgb(Color colour)
    {
        return colour == null ? 0 : colour.getRGB();
    }

    private void ensureMount(MountType type, LocalPoint location, int plane)
    {
        if (mountObject != null && mountObject.isActive() && activeMount == type)
        {
            return;
        }
        clearMount();
        Model model = modelFactory.create(type, config.cartScale(), config.recolourMinecart(),
            config.minecartColour(), config.wheelColour(), config.hubColour());
        if (model == null)
        {
            return;
        }

        RuneLiteObject created = client.createRuneLiteObject();
        created.setModel(model);
        created.setLocation(location, plane);
        created.setRadius(120);
        try
        {
            if (type.mountAnimation >= 0)
            {
                Animation animation = client.loadAnimation(type.mountAnimation);
                if (animation != null)
                {
                    created.setAnimation(animation);
                }
            }
            created.setActive(true);
            CART_OBJECTS.add(created);
            mountObject = created;
            activeMount = type;
        }
        catch (RuntimeException | AssertionError ex)
        {
            removeCart(created);
        }
    }

    boolean isUserMounted()
    {
        return userMounted;
    }

    void toggleMounted()
    {
        userMounted = !userMounted;
        playTogglePoof();
        resetCartState();
    }

    private void playTogglePoof()
    {
        Player player = client.getLocalPlayer();
        if (!config.togglePoof() || player == null || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        try
        {
            player.createSpotAnim(TOGGLE_POOF_SLOT, SpotanimID.SMOKEPUFF, 0, 0);
        }
        catch (RuntimeException | AssertionError ignored)
        {
            // Cosmetic only; never let an unavailable effect block the mount toggle.
        }
    }

    private void resetCartState()
    {
        restorePlayerPose();
        for (RuneLiteObject cart : new ArrayList<>(CART_OBJECTS))
        {
            removeCart(cart);
        }
        CART_OBJECTS.clear();
        mountObject = null;
        activeMount = null;
        modelFactory.clear();
        activeModelSignature = Integer.MIN_VALUE;
    }

    private void restorePlayerPose()
    {
        restoreEquipment();
        if (mountedPlayer != null && originalPose != null)
        {
            originalPose.restore(mountedPlayer);
        }
        mountedPlayer = null;
        originalPose = null;
        activePoseSignature = Integer.MIN_VALUE;
    }

    private void clearMount()
    {
        if (mountObject != null)
        {
            removeCart(mountObject);
            CART_OBJECTS.remove(mountObject);
            mountObject = null;
        }
        activeMount = null;
    }

    private void removeCart(RuneLiteObject cart)
    {
        cart.setActive(false);
        if (client.isRuneLiteObjectRegistered(cart))
        {
            client.removeRuneLiteObject(cart);
        }
    }
}

package com.cartmount;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
final class CartToggleOverlay extends Overlay implements MouseListener
{
    private CartMountPlugin plugin;
    private final ClientThread clientThread;
    private final CartMountConfig config;
    private final BufferedImage icon;

    @Inject
    CartToggleOverlay(ClientThread clientThread, CartMountConfig config)
    {
        this.clientThread = clientThread;
        this.config = config;
        this.icon = loadIcon();
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPosition(OverlayPosition.TOP_LEFT);
    }

    private static BufferedImage loadIcon()
    {
        try (InputStream input = CartToggleOverlay.class.getResourceAsStream("/com/cartmount/cart-toggle.png"))
        {
            return input == null ? null : ImageIO.read(input);
        }
        catch (IOException ignored)
        {
            return null;
        }
    }

    void bind(CartMountPlugin plugin)
    {
        this.plugin = plugin;
    }

    void unbind()
    {
        plugin = null;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        int size = Math.max(24, Math.min(96, config.buttonSize()));
        int padding = Math.max(2, size / 12);
        boolean mounted = plugin != null && plugin.isUserMounted();
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setColor(new Color(18, 20, 24, 210));
        graphics.fillRoundRect(0, 0, size, size, Math.max(7, size / 5), Math.max(7, size / 5));
        graphics.setColor(mounted ? new Color(231, 178, 83) : new Color(115, 120, 128));
        graphics.setStroke(new BasicStroke(Math.max(1f, size / 22f)));
        graphics.drawRoundRect(1, 1, size - 3, size - 3, Math.max(7, size / 5), Math.max(7, size / 5));

        if (icon != null)
        {
            Composite previous = graphics.getComposite();
            if (!mounted)
            {
                graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.48f));
            }
            graphics.drawImage(icon, padding, padding, size - 2 * padding, size - 2 * padding, null);
            graphics.setComposite(previous);
        }
        return new Dimension(size, size);
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        if (SwingUtilities.isLeftMouseButton(event) && getBounds().contains(event.getPoint()))
        {
            event.consume();
            CartMountPlugin current = plugin;
            if (current != null)
            {
                clientThread.invokeLater(current::toggleMounted);
            }
        }
        return event;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseEntered(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseExited(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent event)
    {
        return event;
    }

    @Override
    public MouseEvent mouseMoved(MouseEvent event)
    {
        return event;
    }
}

package com.cartmount;

import net.runelite.api.Model;

final class ModelSafetyValidator
{
    private static final int MAX_VERTICES = 20_000;
    private static final int MAX_FACES = 40_000;
    private static final float MAX_COORDINATE = 131_072f;

    private ModelSafetyValidator()
    {
    }

    static boolean isSafe(Model model)
    {
        if (model == null)
        {
            return false;
        }
        int vertices = model.getVerticesCount();
        int faces = model.getFaceCount();
        if (vertices <= 0 || vertices > MAX_VERTICES || faces <= 0 || faces > MAX_FACES)
        {
            return false;
        }

        float[] x = model.getVerticesX();
        float[] y = model.getVerticesY();
        float[] z = model.getVerticesZ();
        int[] a = model.getFaceIndices1();
        int[] b = model.getFaceIndices2();
        int[] c = model.getFaceIndices3();
        int[] color1 = model.getFaceColors1();
        int[] color2 = model.getFaceColors2();
        int[] color3 = model.getFaceColors3();
        if (!hasLength(x, vertices) || !hasLength(y, vertices) || !hasLength(z, vertices)
            || !hasLength(a, faces) || !hasLength(b, faces) || !hasLength(c, faces)
            || !hasLength(color1, faces) || !hasLength(color2, faces) || !hasLength(color3, faces))
        {
            return false;
        }

        for (int i = 0; i < vertices; i++)
        {
            if (!Float.isFinite(x[i]) || !Float.isFinite(y[i]) || !Float.isFinite(z[i])
                || Math.abs(x[i]) > MAX_COORDINATE || Math.abs(y[i]) > MAX_COORDINATE || Math.abs(z[i]) > MAX_COORDINATE)
            {
                return false;
            }
        }
        for (int i = 0; i < faces; i++)
        {
            if (!validIndex(a[i], vertices) || !validIndex(b[i], vertices) || !validIndex(c[i], vertices))
            {
                return false;
            }
        }

        byte[] transparency = model.getFaceTransparencies();
        short[] textures = model.getFaceTextures();
        if ((transparency != null && transparency.length < faces) || (textures != null && textures.length < faces))
        {
            return false;
        }

        byte[] textureFaces = model.getTextureFaces();
        if (textureFaces != null)
        {
            if (textureFaces.length < faces)
            {
                return false;
            }
            int[] textureA = model.getTexIndices1();
            int[] textureB = model.getTexIndices2();
            int[] textureC = model.getTexIndices3();
            for (int i = 0; i < faces; i++)
            {
                int textureFace = textureFaces[i];
                if (textureFace == -1)
                {
                    continue;
                }
                int index = textureFace & 0xFF;
                if (!hasIndex(textureA, index) || !hasIndex(textureB, index) || !hasIndex(textureC, index)
                    || !validIndex(textureA[index], vertices) || !validIndex(textureB[index], vertices)
                    || !validIndex(textureC[index], vertices))
                {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean hasLength(float[] values, int length)
    {
        return values != null && values.length >= length;
    }

    private static boolean hasLength(int[] values, int length)
    {
        return values != null && values.length >= length;
    }

    private static boolean hasIndex(int[] values, int index)
    {
        return values != null && index >= 0 && index < values.length;
    }

    private static boolean validIndex(int index, int size)
    {
        return index >= 0 && index < size;
    }
}

